def compute_output(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    sizes_map = {}

    def count_island(r, c):
        size = 0
        cells = []
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            cr, cc = stack.pop()
            size += 1
            cells.append((cr, cc))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 8 and not visited[nr][nc]:
                        visited[nr][nc] = True
                        stack.append((nr, nc))
        return cells, size

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8 and not visited[r][c]:
                cells, size = count_island(r, c)
                for cr, cc in cells:
                    sizes_map[(cr, cc)] = size

    # Build output: 8 -> island size, keep 9s and special values
    output = [[0 for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8:
                output[r][c] = sizes_map[(r, c)]
            else:
                output[r][c] = grid[r][c]

    return output

