def connected_horizontal(grid, val):
    count = 0
    current = 0
    result = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == val:
                current += 1
            else:
                if current > 0:
                    result.append(current)
                    current = 0
        if current > 0:
            result.append(current)
            current = 0
    return result

def connected_vertical(grid, val):
    count = 0
    result = []
    for c in range(len(grid[0])):
        for r in range(len(grid)):
            if grid[r][c] == val:
                count += 1
            else:
                if count > 0:
                    result.append(count)
                    count = 0
        if count > 0:
            result.append(count)
        count = 0
    return result

